// <auto-generated companion /> — UTF-8 marshalling for spark_* string parameters.
#nullable enable
using System.Text;

namespace Spark.Bindings;

internal static class InteropUtf8
{
    public static unsafe void WithUtf8(string? text, Action<IntPtr> action)
    {
        if (text is null)
        {
            action(IntPtr.Zero);
            return;
        }

        var byteCount = Encoding.UTF8.GetByteCount(text);
        var buffer = new byte[byteCount + 1];
        Encoding.UTF8.GetBytes(text, 0, text.Length, buffer, 0);
        fixed (byte* p = buffer)
        {
            action((IntPtr)p);
        }
    }
}
